// smc-email-verify (2026-10-11): the email verification of agreement clause 5.8(b) / Schedule 2 criterion 1, inside the
// CRM. Pure functions over automation/ctwa/capture-v2.js (issueEmailVerification / verifyEmailToken / verifyEmailCode,
// tested in tests/capture-v2.test.mjs). The workflow (automation/SUB-email-verify.json, generated by
// build-sub-workflows.mjs) does the SQL, the Resend call and the WhatsApp reply. Code node form:
//   const L = require('lv-automation').subEmailVerify;
//
// One email, two ways to confirm (capture-v2 COPY.verify_body): a one-tap link https://sortmycover.co.za/v/<token>
// (served by the same sub-workflow's GET webhook v/:token) and a 6-digit code the lead types on WhatsApp (W07 routes
// it here: route 'email_code'). Sent from hello@sortmycover.co.za through Resend (RESEND_API_KEY, the CRM's existing
// key). Only sha256(lead_id|code) is stored; the code exists in the email and nowhere else.
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const C = require('../ctwa/capture-v2.js');

export const RESEND_URL = 'https://api.resend.com/emails';
export const SMC_EMAIL_RELAY_URL = 'https://cmsylaupctrbsvzrgzwy.supabase.co/functions/v1/smc-email-send';
export const DEFAULT_FROM = 'SortMyCover <hello@sortmycover.co.za>';
export const RESEND_GAP_MS = 10 * 60 * 1000; // one email per 10 minutes per lead (a repeat issue inside it is a no-op)
const first = (s) => String(s || '').trim().split(/\s+/)[0] || '';

export const REPLY = {
  ok: 'Thanks, your email is confirmed.',
  already: 'Your email is already confirmed. Thank you.',
  wrong: "That code doesn't match. Please check the email we sent you and try again.",
  expired: 'That code has expired. We have emailed you a new one.',
  locked: 'That code has been tried too many times, so it no longer works. Your booking is not affected.',
  none_issued: "We haven't sent you a code yet.",
};

/** Normalise the sub-call input: { op: 'issue', lead_id } | { op: 'code', lead_id, code, wamid?, to? }. */
export function normalise(i = {}) {
  const op = ['issue', 'code'].includes(i.op) ? i.op : null;
  const lead_id = /^[0-9a-f-]{36}$/i.test(String(i.lead_id || '')) ? String(i.lead_id) : null;
  const code = op === 'code' ? String(i.code || '').replace(/\D/g, '').slice(0, 6) : null;
  const missing = [!op && 'op', !lead_id && 'lead_id', op === 'code' && (!code || code.length !== 6) && 'code'].filter(Boolean);
  return { op, lead_id, code, wamid: i.wamid || null, to: i.to || null, valid: missing.length === 0, missing };
}

/**
 * lead row (id, first_name, email, email_verified, email_verify_sent_at, opted_out_at, adviser_name) -> what to do.
 * { action: 'skip', reason } | { action: 'send', set, resend: { url, headers, body }, activity }.
 */
export function issuePlan(lead, env = {}, now = Date.now()) {
  if (!lead || !lead.id) return { action: 'skip', reason: 'unknown_lead' };
  if (lead.opted_out_at) return { action: 'skip', reason: 'opted_out' };
  if (!lead.email) return { action: 'skip', reason: 'no_email' };
  if (lead.email_verified === true || lead.email_verified === 't') return { action: 'skip', reason: 'already_verified' };
  const last = lead.email_verify_sent_at ? Date.parse(lead.email_verify_sent_at) : NaN;
  if (Number.isFinite(last) && now - last < RESEND_GAP_MS) return { action: 'skip', reason: 'recently_sent' };
  if (!env.EMAIL_VERIFY_SECRET || String(env.EMAIL_VERIFY_SECRET).length < 32) return { action: 'skip', reason: 'secret_missing' };
  // 17 Oct 2026: without a Resend key on the n8n server the email goes through the smc-email-send function (the key is a
  // Supabase secret there), authorised by the n8n relay token.
  const relay = !env.RESEND_API_KEY && env.LINDI_RELAY_TOKEN;
  if (!env.RESEND_API_KEY && !relay) return { action: 'skip', reason: 'resend_key_missing' };
  const iss = C.issueEmailVerification(lead, { secret: env.EMAIL_VERIFY_SECRET, now, baseUrl: env.VERIFY_BASE_URL || 'https://sortmycover.co.za', adviser: first(lead.adviser_name) || 'your adviser' });
  if (!iss) return { action: 'skip', reason: 'no_email' };
  const m = iss.mail.message;
  const body = { from: env.VERIFY_EMAIL_FROM || DEFAULT_FROM, to: [lead.email], subject: m.subject, text: m.body.content, ...(env.VERIFY_EMAIL_REPLY_TO ? { reply_to: env.VERIFY_EMAIL_REPLY_TO } : {}),
    tags: [{ name: 'flow', value: 'email_verification' }] };
  return {
    action: 'send',
    set: iss.set,
    resend: { url: relay ? env.SMC_EMAIL_RELAY_URL || SMC_EMAIL_RELAY_URL : RESEND_URL, headers: { Authorization: `Bearer ${relay ? env.LINDI_RELAY_TOKEN : env.RESEND_API_KEY}`, 'Content-Type': 'application/json', 'Idempotency-Key': `ev:${lead.id}:${iss.set.email_verify_sent_at}` }, body },
    activity: { activity_type: 'email_verify_sent', payload: { via: 'resend', expires_at: iss.set.email_verify_expires_at } },
  };
}

/** Resend response -> { ok, external_id, error }. 200 { id } on success. */
export function interpretResend(res = {}) {
  const body = res.body !== undefined ? res.body : res;
  const code = res.statusCode || res.status;
  if (body && body.id && !(code && code >= 400)) return { ok: true, external_id: String(body.id), error: null };
  return { ok: false, external_id: null, error: String((body && (body.message || body.name)) || res.error || 'send_failed').slice(0, 300) };
}

/** A typed code -> { ok, set, reply, activity }. */
export function codePlan(lead, code, now = Date.now()) {
  const r = C.verifyEmailCode(code, lead, { now });
  const reply = r.ok ? (r.already ? REPLY.already : REPLY.ok) : REPLY[r.reason] || REPLY.wrong;
  // expired -> the workflow issues a fresh code at once (same 10-minute gap rule), so the reply's promise is kept.
  return { ok: !!r.ok, reason: r.reason || null, reissue: r.reason === 'expired', set: r.set || {}, reply, activity: { activity_type: r.ok ? 'email_verified' : 'email_verify_failed', payload: { via: 'code', reason: r.reason || null } } };
}

/** The lead id inside an ev1 link token (looked up before the signature is checked; the check binds it to the email). */
export function leadIdFromToken(token) {
  const p = String(token || '').split('.');
  return p.length === 4 && p[0] === 'ev1' && /^[0-9a-f-]{36}$/i.test(p[1]) ? p[1] : null;
}

/** The one-tap link -> { ok, set, page, activity }. Every failure shows the same page (no oracle). */
export function linkPlan(token, lead, env = {}, now = Date.now()) {
  const bad = { ok: false, set: {}, status: 404, page: page('This link is not valid any more', 'Reply on WhatsApp and we will send you a new one.') };
  if (!lead || !env.EMAIL_VERIFY_SECRET) return bad;
  if (lead.email_verified === true || lead.email_verified === 't') return { ok: true, set: {}, status: 200, page: page('Your email is confirmed', 'You can close this page.'), activity: null };
  const r = C.verifyEmailToken(token, lead, { secret: env.EMAIL_VERIFY_SECRET, now });
  if (!r.ok) return { ...bad, reason: r.reason };
  return { ok: true, set: r.set, status: 200, page: page('Your email is confirmed', 'Thank you. You can close this page.'), activity: { activity_type: 'email_verified', payload: { via: 'link' } } };
}

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
export function page(title, line) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title>`
    + '<style>body{font-family:system-ui,sans-serif;margin:0;padding:48px 16px;background:#f7f7f5;color:#1d1d1b}main{max-width:420px;margin:auto;background:#fff;border-radius:12px;padding:32px}h1{font-size:22px;margin:0 0 12px}p{margin:0;line-height:1.5}</style>'
    + `</head><body><main><h1>${esc(title)}</h1><p>${esc(line)}</p><p style="margin-top:24px;color:#777">SortMyCover</p></main></body></html>`;
}
